// ---------------------------------------------------------------
// Filtra os contatos do Bling que interessam pro dashboard.
// Roda em cima da lista paginada (todas as paginas ja vieram).
// ---------------------------------------------------------------

// Vira true se voce tambem quiser puxar pessoa fisica (CPF, 11 digitos).
const INCLUIR_CPF = false;

// Situacoes do Bling: 'A' = Ativo, 'I' = Inativo, 'S' = Sem movimento.
const SITUACOES_ACEITAS = ['A'];

const entrada = $input.all();
const saida = [];
let semDoc = 0, pessoaFisica = 0, inativos = 0;

for (const item of entrada) {
  const c = item.json ?? {};
  const doc = String(c.numeroDocumento ?? '').replace(/\D/g, '');

  if (!doc) { semDoc++; continue; }

  const ehCnpj = doc.length === 14;
  const ehCpf  = doc.length === 11;

  if (!ehCnpj && !ehCpf) { semDoc++; continue; }
  if (ehCpf && !INCLUIR_CPF) { pessoaFisica++; continue; }

  const situacao = c.situacao ?? null;
  if (situacao && !SITUACOES_ACEITAS.includes(situacao)) { inativos++; continue; }

  saida.push({
    json: {
      id: c.id,
      nome: c.nome ?? null,
      numeroDocumento: doc,
      tipoDoc: ehCnpj ? 'CNPJ' : 'CPF',
      situacao,
      // guardados como fallback caso o detalhe nao traga telefone
      telefoneLista: c.telefone ?? null,
      celularLista: c.celular ?? null,
    },
  });
}

console.log('[Contatos] recebidos=' + entrada.length +
            ' | aprovados=' + saida.length +
            ' | sem doc valido=' + semDoc +
            ' | pessoa fisica ignorada=' + pessoaFisica +
            ' | inativos=' + inativos);

return saida;

// ---------------------------------------------------------------
// Monta o JSON final, ja no formato que o dashboard espera.
// Cole a saida do campo "leads" no chat.
// ---------------------------------------------------------------

const detalhados = $json.contatos_detalhados ?? [];

// Telefone no padrao do banco: 55 + DDD + numero (so digitos).
function normalizarTelefone(...candidatos) {
  for (const raw of candidatos) {
    if (!raw) continue;
    let d = String(raw).replace(/\D/g, '');
    if (!d) continue;
    d = d.replace(/^0+/, '');
    // tira o 55 pra analisar o numero local
    let local = d;
    if (local.length > 11 && local.startsWith('55')) local = local.slice(2);
    if (local.length === 10 || local.length === 11) return '55' + local;
  }
  return null;
}

// Chute de segmento pelo nome. E so um palpite - revise depois no dashboard.
function chutarSegmento(nome) {
  const n = (nome || '').toLowerCase();
  if (/hotel|pousada|resort|hostel|motel/.test(n)) return 'HOTELARIA';
  if (/academia|fitness|gym|crossfit|pilates/.test(n)) return 'ACADEMIA';
  if (/evento|buffet|bufe|recep[cç]|festa|salao/.test(n)) return 'EVENTOS';
  if (/distribuidor|atacad|represent|comercial|mercadinho|mercado|supermerc/.test(n)) return 'DISTRIBUIDOR';
  if (/franquia|franchis/.test(n)) return 'FRANQUIA';
  if (/restaurante|lanchonete|pizza|churrasc|refei|self.?service|espetinho|burger|hamburg|sushi|padaria|tapiocaria|creperia|acai|sorvet|bar\b|cafe|bistro|comida|cozinha|grill|espeto/.test(n)) return 'RESTAURANTE';
  return 'OUTRO';
}

const leads = [];
const semTelefone = [];

for (const item of detalhados) {
  // O HTTP de detalhe responde { data: { ...contato } }
  const c = item?.data ?? item ?? {};
  const geral = c?.endereco?.geral ?? {};

  const doc = String(c.numeroDocumento ?? '').replace(/\D/g, '');
  const empresa = (c.nome ?? '').trim();
  if (!empresa || !doc) continue;

  const contatoWhatsapp = normalizarTelefone(c.celular, c.telefone);

  const registro = {
    empresa,
    cnpjCpf: doc,
    contatoWhatsapp,
    cidade: (geral.municipio ?? '').trim() || null,
    uf: (geral.uf ?? '').trim().toUpperCase() || null,
    segmentoSugerido: chutarSegmento(empresa),
    blingContatoId: c.id != null ? String(c.id) : null,
    email: (c.email ?? '').trim() || null,
  };

  if (!contatoWhatsapp) semTelefone.push(registro);
  else leads.push(registro);
}

// Ordena por nome pra facilitar a conferencia
leads.sort((a, b) => a.empresa.localeCompare(b.empresa, 'pt-BR'));
semTelefone.sort((a, b) => a.empresa.localeCompare(b.empresa, 'pt-BR'));

console.log('[Dashboard] prontos=' + leads.length + ' | sem telefone=' + semTelefone.length);

return [{
  json: {
    resumo: {
      total_detalhados: detalhados.length,
      prontos_para_importar: leads.length,
      sem_telefone: semTelefone.length,
      gerado_por: 'n8n - Bling contatos -> Fruta Polpas Hub',
    },
    leads,
    leads_sem_telefone: semTelefone,
  },
}];
